   160→PyMODINIT_FUNC PyInit_ujson(void)
   161→{
   162→  PyObject* module;
   163→
   164→#ifndef PYPY_VERSION
   165→  // This function is not supported in PyPy.
   166→  if ((module = PyState_FindModule(&moduledef)) != NULL)
   167→  {
   168→    Py_INCREF(module);
   169→    return module;
   170→  }
   171→#endif
   172→
   173→  module = PyModule_Create(&moduledef);
   174→  if (module == NULL)
   175→  {
   176→    return NULL;
   177→  }
   178→
   179→  PyModule_AddStringConstant(module, "__version__", UJSON_VERSION);
   180→
   181→#ifndef PYPY_VERSION
   182→  PyObject *mod_decimal = PyImport_ImportModule("decimal");
   183→  if (mod_decimal)
   184→  {
   185→    PyObject* type_decimal = PyObject_GetAttrString(mod_decimal, "Decimal");
   186→    assert(type_decimal != NULL);
   187→    modulestate(module)->type_decimal = type_decimal;
   188→    Py_DECREF(mod_decimal);
   189→  }
   190→  else
   191→    PyErr_Clear();
   192→#endif
   193→
   194→  JSONDecodeError = PyErr_NewException("ujson.JSONDecodeError", PyExc_ValueError, NULL);
   195→  Py_XINCREF(JSONDecodeError);
   196→  if (PyModule_AddObject(module, "JSONDecodeError", JSONDecodeError) < 0)
   197→  {
   198→    Py_XDECREF(JSONDecodeError);
   199→    Py_CLEAR(JSONDecodeError);
   200→    Py_DECREF(module);
   201→    return NULL;
   202→  }
   203→
   204→  return module;
   205→}
