   163→PyObject* JSONToObj(PyObject* self, PyObject *args, PyObject *kwargs)
   164→{
   165→  PyObject *ret;
   166→  PyObject *sarg;
   167→  PyObject *arg;
   168→  JSONObjectDecoder decoder =
   169→  {
   170→    Object_newString,
   171→    Object_objectAddKey,
   172→    Object_arrayAddItem,
   173→    Object_newTrue,
   174→    Object_newFalse,
   175→    Object_newNull,
   176→    Object_newNaN,
   177→    Object_newPosInf,
   178→    Object_newNegInf,
   179→    Object_newObject,
   180→    Object_newArray,
   181→    Object_newInteger,
   182→    Object_newLong,
   183→    Object_newUnsignedLong,
   184→    Object_newIntegerFromString,
   185→    Object_newDouble,
   186→    Object_releaseObject,
   187→    PyObject_Malloc,
   188→    PyObject_Free,
   189→    PyObject_Realloc
   190→  };
   191→
   192→  decoder.prv = NULL;
   193→
   194→  if (!PyArg_ParseTupleAndKeywords(args, kwargs, "O", g_kwlist, &arg))
   195→  {
   196→      return NULL;
   197→  }
   198→
   199→  Py_buffer buffer;
   200→  size_t sarg_length;
   201→  char * raw;
   202→  bool is_bytes_like = !PyObject_GetBuffer(arg, &buffer, PyBUF_C_CONTIGUOUS);
   203→  if (is_bytes_like)
   204→  {
   205→    #ifdef PYPY_VERSION
   206→      // PyPy's buffer protocol implementation is buggy: https://foss.heptapod.net/pypy/pypy/-/issues/3872
   207→      if (!PyBytes_Check(arg) && !PyByteArray_Check(arg)) {
   208→        PyBuffer_Release(&buffer);
   209→        PyErr_Format(PyExc_TypeError, "Arbitrary bytes-like objects are not supported on PyPy, Use either string, bytes, or bytearray");
   210→        return NULL;
   211→      }
   212→    #endif
   213→    raw = buffer.buf;
   214→    sarg_length = buffer.len;
   215→  }
   216→  else
   217→  {
   218→    PyErr_Clear();
   219→    if (PyUnicode_Check(arg))
   220→    {
   221→      sarg = PyUnicode_AsEncodedString(arg, NULL, "surrogatepass");
   222→      if (sarg == NULL)
   223→      {
   224→        //Exception raised above us by codec according to docs
   225→        return NULL;
   226→      }
   227→      sarg_length = PyBytes_Size(sarg);
   228→      raw = PyBytes_AsString(sarg);
   229→    }
   230→    else
   231→    {
   232→      #ifdef PYPY_VERSION
   233→        PyErr_Format(PyExc_TypeError, "Expected string, bytes, or bytearray");
   234→      #else
   235→        PyErr_Format(PyExc_TypeError, "Expected string or C-contiguous bytes-like object");
   236→      #endif
   237→      return NULL;
   238→    }
   239→  }
   240→
   241→  decoder.errorStr = NULL;
   242→  decoder.errorOffset = NULL;
   243→
   244→  decoder.s2d = NULL;
   245→  dconv_s2d_init(&decoder.s2d, DCONV_S2D_ALLOW_TRAILING_JUNK, 0.0, 0.0, "Infinity", "NaN");
   246→
   247→  ret = JSON_DecodeObject(&decoder, raw, sarg_length);
   248→
   249→  dconv_s2d_free(&decoder.s2d);
   250→
   251→  if (!is_bytes_like)
   252→  {
   253→    Py_DECREF(sarg);
   254→  }
   255→  else
   256→  {
   257→    PyBuffer_Release(&buffer);
   258→  }
   259→
   260→  // Check if a Python error occurred during decoding
   261→  if (PyErr_Occurred())
   262→  {
   263→    if (ret)
   264→    {
   265→        Py_DECREF( (PyObject *) ret);
   266→    }
   267→    return NULL;
   268→  }
   269→
   270→  if (decoder.errorStr)
   271→  {
   272→    /*
   273→    FIXME: It's possible to give a much nicer error message here with actual failing element in input etc*/
   274→
   275→    PyErr_Format (JSONDecodeError, "%s", decoder.errorStr);
   276→
   277→    if (ret)
   278→    {
   279→        Py_DECREF( (PyObject *) ret);
   280→    }
   281→
   282→    return NULL;
   283→  }
   284→
   285→  return ret;
   286→}
