   971→    if (!enc->start)
   972→    {
   973→      SetError(obj, enc, "Could not reserve memory block");
   974→      return NULL;
   975→    }
   976→    enc->heap = 1;
   977→  }
   978→  else
   979→  {
   980→    enc->start = _buffer;
   981→    enc->heap = 0;
   982→  }
   983→
